        if '/' in r:
            d, t = r.split('/')
            m = re.match(r'([+-]?)(\d+)(?::(\d+))?(?::(\d+))?', t)
            secs = int(m.group(2)) * 3600 + int(m.group(3) or 0) * 60 + int(m.group(4) or 0)
            if m.group(1) == '-': secs = -secs
