use datelib::datetime as dt;
use std::io::{self, BufRead, Write};

#[derive(Debug, Clone)]
enum J { Null, Bool(bool), Num(f64), Str(String), Arr(Vec<J>), Obj(Vec<(String, J)>) }

struct P<'a> { s: &'a [u8], i: usize }
impl<'a> P<'a> {
    fn ws(&mut self) { while self.i < self.s.len() && (self.s[self.i] as char).is_whitespace() { self.i += 1; } }
    fn val(&mut self) -> J {
        self.ws();
        match self.s[self.i] {
            b'n' => { self.i += 4; J::Null }
            b't' => { self.i += 4; J::Bool(true) }
            b'f' => { self.i += 5; J::Bool(false) }
            b'"' => J::Str(self.string()),
            b'[' => { self.i += 1; let mut v = vec![]; loop { self.ws(); if self.s[self.i] == b']' { self.i += 1; break; } v.push(self.val()); self.ws(); if self.s[self.i] == b',' { self.i += 1; } } J::Arr(v) }
            b'{' => { self.i += 1; let mut v = vec![]; loop { self.ws(); if self.s[self.i] == b'}' { self.i += 1; break; } let k = self.string(); self.ws(); self.i += 1; let x = self.val(); v.push((k, x)); self.ws(); if self.s[self.i] == b',' { self.i += 1; } } J::Obj(v) }
            _ => { let st = self.i; while self.i < self.s.len() && b"+-0123456789.eE".contains(&self.s[self.i]) { self.i += 1; } J::Num(std::str::from_utf8(&self.s[st..self.i]).unwrap().parse().unwrap()) }
        }
    }
    fn string(&mut self) -> String {
        self.i += 1; let mut out = String::new(); let mut hi: Option<u32> = None;
        loop {
            let c = self.s[self.i]; self.i += 1;
            if c == b'"' { break; }
            if c == b'\\' {
                let e = self.s[self.i]; self.i += 1;
                match e { b'n' => out.push('\n'), b't' => out.push('\t'), b'r' => out.push('\r'), b'b' => out.push('\u{8}'), b'f' => out.push('\u{c}'),
                    b'u' => { let h = std::str::from_utf8(&self.s[self.i..self.i+4]).unwrap(); self.i += 4; let v = u32::from_str_radix(h, 16).unwrap();
                        if (0xD800..0xDC00).contains(&v) { hi = Some(v); continue; }
                        if (0xDC00..0xE000).contains(&v) { if let Some(h) = hi.take() { out.push(char::from_u32(0x10000 + ((h - 0xD800) << 10) + (v - 0xDC00)).unwrap()); } continue; }
                        out.push(char::from_u32(v).unwrap()); }
                    _ => out.push(e as char) }
            } else {
                // utf8 continuation: copy raw
                let st = self.i - 1; let mut en = self.i; while en < self.s.len() && (self.s[en] & 0xC0) == 0x80 { en += 1; }
                out.push_str(std::str::from_utf8(&self.s[st..en]).unwrap()); self.i = en;
            }
        }
        out
    }
}

fn js_tostring(v: &J) -> String {
    match v { J::Null => "null".into(), J::Bool(b) => b.to_string(), J::Num(n) => { if *n == n.trunc() && n.abs() < 1e21 { format!("{}", *n as i64) } else { format!("{}", n) } }, J::Str(s) => s.clone(), J::Arr(_) => "".into(), J::Obj(_) => "[object Object]".into() }
}
fn js_tonumber(v: &J) -> f64 {
    match v { J::Null => 0.0, J::Bool(b) => if *b { 1.0 } else { 0.0 }, J::Num(n) => *n, J::Str(s) => s.trim().parse().unwrap_or(f64::NAN), _ => f64::NAN }
}
fn js_toboolean(v: &J) -> bool {
    match v { J::Null => false, J::Bool(b) => *b, J::Num(n) => *n != 0.0 && !n.is_nan(), J::Str(s) => !s.is_empty(), _ => true }
}
fn json_str(s: &str) -> String {
    let mut o = String::from("\"");
    for c in s.chars() { match c { '"' => o.push_str("\\\""), '\\' => o.push_str("\\\\"), '\n' => o.push_str("\\n"), c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)), c => o.push(c) } }
    o.push('"'); o
}

const ORDER: [&str; 20] = ["localeMatcher", "calendar", "numberingSystem", "hour12", "hourCycle", "timeZone", "weekday", "era", "year", "month", "day", "dayPeriod", "hour", "minute", "second", "fractionalSecondDigits", "timeZoneName", "formatMatcher", "dateStyle", "timeStyle"];

fn run(t: f64, locales: &[String], opts: &[(String, J)], mode: &str) -> Result<String, dt::DateTimeError> {
    if matches!(mode, "ls" | "lds" | "lts") && t.is_nan() { return Ok(json_str("Invalid Date")); }
    dt::canonicalize_locale_list(locales)?;
    let mut o = dt::DateTimeFormatOptions::new();
    for k in ORDER {
        if let Some((_, v)) = opts.iter().find(|(kk, _)| kk == k) {
            if let J::Null = v { if k != "hour12" && k != "fractionalSecondDigits" { o.set(k, "null")?; continue; } }
            match k {
                "hour12" => o.set_hour12(js_toboolean(v)),
                "fractionalSecondDigits" => o.set_fractional_second_digits(js_tonumber(v))?,
                _ => o.set(k, &js_tostring(v))?,
            }
        }
    }
    match mode {
        "dtf" => { let f = dt::DateTimeFormat::new(locales, &o)?; Ok(json_str(&f.format(t)?)) }
        "ls" => Ok(json_str(&dt::to_locale_string(t, locales, &o)?)),
        "lds" => Ok(json_str(&dt::to_locale_date_string(t, locales, &o)?)),
        "lts" => Ok(json_str(&dt::to_locale_time_string(t, locales, &o)?)),
        "parts" => { let f = dt::DateTimeFormat::new(locales, &o)?; let p = f.format_to_parts(t)?; Ok(format!("[{}]", p.iter().map(|x| format!("{{\"type\":{},\"value\":{}}}", json_str(x.kind), json_str(&x.value))).collect::<Vec<_>>().join(","))) }
        "ro" => { let f = dt::DateTimeFormat::new(locales, &o)?; let r = f.resolved_options(); Ok(format!("{{{}}}", r.iter().map(|(k, v)| format!("{}:{}", json_str(k), match v { dt::ResolvedValue::Str(s) => json_str(s), dt::ResolvedValue::Bool(b) => b.to_string(), dt::ResolvedValue::Number(n) => n.to_string() })).collect::<Vec<_>>().join(","))) }
        _ => Ok("?".into()),
    }
}

fn main() {
    let stdin = io::stdin();
    let mut out = io::BufWriter::new(io::stdout());
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        // line: JSON array [t, locales(array|null), options(object|null), mode]
        let mut p = P { s: line.as_bytes(), i: 0 };
        let v = p.val();
        let a = match v { J::Arr(a) => a, _ => panic!() };
        let t = match &a[0] { J::Num(n) => *n, J::Null => f64::NAN, J::Str(s) if s == "NaN" => f64::NAN, _ => f64::NAN };
        let locales: Vec<String> = match &a[1] { J::Arr(x) => x.iter().map(|y| js_tostring(y)).collect(), J::Str(s) => vec![s.clone()], _ => vec![] };
        let opts: Vec<(String, J)> = match &a[2] { J::Obj(o) => o.clone(), _ => vec![] };
        let mode = match &a[3] { J::Str(s) => s.clone(), _ => "dtf".into() };
        let r = match run(t, &locales, &opts, &mode) { Ok(s) => s, Err(e) => format!("THROW {}", e) };
        writeln!(out, "{}", r).unwrap();
    }
}
